let sceneryDefs=new Map();
function sceneryAsset(id,x,y,w,h,prefix){
 const a=SCENERY[id];if(!a)return '';
 const b=a.bounds,symbolId='scenery-'+id.replace(/[^a-z0-9]/gi,'-');
 if(!sceneryDefs.has(id)){
  const body=a.svg.replace(/^<svg\b[^>]*>/,'').replace(/<\/svg>\s*$/,'');
  sceneryDefs.set(id,`<symbol id="${symbolId}" viewBox="${b.x} ${b.y} ${b.width} ${b.height}" overflow="visible">${namespaceArt(body,symbolId+'-')}</symbol>`);
 }
 return `<g data-asset="${id}"><use href="#${symbolId}" x="${x}" y="${y}" width="${w}" height="${h}"/></g>`;
}
function outdoorMap(scene,d){
 sceneryDefs=new Map();
 const places=scene.places,width=1100,height=Math.max(780,620+places.length*35),blockers=[],objects=[];
 let terrain=`<rect width="${width}" height="${height}" fill="#f1e5ca"/><path d="M50 190Q250 40 620 125T1050 300L1010 ${height-140}Q700 ${height+10} 160 ${height-100}Q-10 500 50 190Z" fill="#c7cba9" opacity=".43"/><path d="M90 500Q280 340 500 510T1010 570" fill="none" stroke="#d7c7a2" stroke-width="85" opacity=".17"/>`;
 const locations=[[165,190],[695,180],[640,510],[155,530],[430,140],[425,620],[850,410]];
 for(const [i,p]of places.entries()){
  let [x,y]=locations[i%locations.length];y+=Math.floor(i/locations.length)*230;
  const semantic=key(p.type||p.name),water=/lake|river|pond|hồ|sông|ao/.test(semantic),open=/garden|yard|clearing|field|vườn|sân|bãi/.test(semantic);
  const w=water?340:open?300:230,h=water?220:open?210:200;
  p.bounds=[x,y,w,h];p.geometry={outdoor:true,water,open};let art='';
  if(water){
   art=`<path data-forbidden="water" d="M${x} ${y+90}Q${x+35} ${y-25} ${x+180} ${y+15}T${x+w} ${y+110}Q${x+w-10} ${y+h+15} ${x+150} ${y+h}T${x} ${y+90}Z" fill="#8fae9e" stroke="#d7c9a4" stroke-width="9"/><path d="M${x+45} ${y+105}q65 -15 140 0m-95 35q65 12 155 -4" fill="none" stroke="#c5d5c2" stroke-width="2" opacity=".6"/>`;
   blockers.push({x,y,w,h,ellipse:true});
  }else if(open){
   art=`<ellipse cx="${x+w/2}" cy="${y+h/2}" rx="${w/2}" ry="${h/2}" fill="#c9caa5" opacity=".45"/>`;
   art+=sceneryAsset('landscape.garden-bench',x+35,y+130,65,40,'o'+i+'bench-');
  }else{
   const id=/tower|tháp/.test(semantic)?'architecture.owlery':/storage|shed|kho/.test(semantic)?'house.shed':/shop|tiệm/.test(semantic)?'architecture.shop':/inn|quán/.test(semantic)?'architecture.inn':i%2?'house.timber':'architecture.cottage';
   art=`<ellipse cx="${x+w/2}" cy="${y+h-8}" rx="${w*.48}" ry="18" fill="#8d9774" opacity=".16"/>`+`<g data-forbidden="building" data-occluder="building" data-depth="${y+h}">${sceneryAsset(id,x,y,w,h,'o'+i+'-')}</g>`;
   blockers.push({x:x+12,y:y+20,w:w-24,h:h-20});
  }
  objects.push({depth:y+h,svg:`<g data-id="${escapeXML(p.id)}" role="button" tabindex="0" aria-label="${escapeXML(p.name)}">${art}<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="transparent"/></g>`});
  (p.props||[]).forEach((prop,j)=>objects.push({depth:y+h+25,svg:`<g data-prop-fallback="true"><path d="M${x+20+j*22} ${y+h+12}l7 7 -7 7 -7 -7Z" fill="#d8c6a6" stroke="#8d7658"/><title>${escapeXML(prop.name)} × ${prop.count}</title></g>`}));
 }
 for(let i=0;i<44;i++){
  const x=55+(i*239%990),y=65+(i*173%(height-130)),w=32+(i%4)*13,h=w*1.25;
  if(places.some(p=>{const[a,b,c,e]=p.bounds;return x+w>a-20&&x<a+c+20&&y+h>b-20&&y<b+e+35}))continue;
  const id=i%6===0?'terrain.boulder':['architecture.tree','tree.pine','tree.umbrella','tree.bare','plant.bush'][i%5];
  objects.push({depth:y+h,svg:sceneryAsset(id,x,y,w,h,'land'+i+'-')});
 }
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}"><defs>${[...sceneryDefs.values()].join('')}</defs><g data-layer="terrain">${terrain}</g><g data-layer="architecture">${objects.sort((a,b)=>a.depth-b.depth).map(o=>o.svg).join('')}</g></svg>`;
 return {kind:'outdoor',title:d.meta.areaName||d.pcPlace,bounds:[0,0,width,height],places,svg,safeFloor:(x,y,pad=0)=>x-pad>=0&&y-pad>=0&&x+pad<=width&&y+pad<=height&&!blockers.some(r=>r.ellipse?((x-r.x-r.w/2)/(r.w/2+pad))**2+((y-r.y-r.h/2)/(r.h/2+pad))**2<=1:x+pad>=r.x&&x-pad<=r.x+r.w&&y+pad>=r.y&&y-pad<=r.y+r.h)};
}
function styleIndoor(markup,plan,places){
 const doc=new DOMParser().parseFromString(markup,'image/svg+xml'),root=doc.documentElement;
 const finishes={POTIONS_LAB:['octagon','dark'],OFFICE:['wood','limestone'],STORAGE:['brick','stone'],CLASSROOM:['tile','plaster']};
 const finish=r=>{const p=places[r.index],base=finishes[recipeId(p?.type)]||['mosaic','wainscot'],a=p?.architecture||{};return [['tile','wood','brick','octagon','mosaic','herringbone','diamond','cobble'].includes(a.floor)?a.floor:base[0],['stone','dark','timber','wainscot','plaster','brick','ashlar','panel','limestone','rubble'].includes(a.wall)?a.wall:base[1]];};
 for(const r of plan.rooms){const[floor]=finish(r);for(const n of root.querySelectorAll('[data-layer="floors"] rect'))if(Math.abs(+n.getAttribute('x')-r.x)<.1&&Math.abs(+n.getAttribute('y')-r.y)<.1)n.setAttribute('fill',`url(#floor-${floor})`);}
 const walls=[...plan.walls].sort((a,b)=>(a.axis==='H'?a.at:a.b)-(b.axis==='H'?b.at:b.b)||a.at-b.at);
 [...root.querySelectorAll('[data-wall]')].forEach((n,i)=>{const wall=walls[i];if(!wall)return;const r=plan.rooms.find(r=>r.id===(wall.A?.kind==='room'?wall.A.id:wall.B?.id));if(r)n.querySelector('path').setAttribute('fill',`url(#wall-${finish(r)[1]})`);});
 const layer=root.querySelector('[data-layer="architecture"]');
 for(const w of plan.walls.filter(w=>w.axis==='V'&&(w.A?.kind==='hall'||w.B?.kind==='hall')&&w.b-w.a>100)){
  const at=(w.a+w.b)/2;
  if([...plan.openings.doors,...plan.openings.windows].some(o=>o.ln===w&&Math.abs(o.at-at)<o.width/2+25))continue;
  const g=doc.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('data-corridor-decor','vertical');g.setAttribute('transform',`translate(${w.at+3} ${at-18}) scale(.55)`);g.innerHTML=CORRIDORS.decorate('candle');layer.append(g);
 }
 return new XMLSerializer().serializeToString(root);
}
function buildMap(scene,d){return d.mapMode==='outdoor'?outdoorMap(scene,d):indoorMap(scene,d);}
function generatedActorPoint(map,place,spot){
 if(!place.bounds||!spot)return null;
 const [x,y,w,h]=place.bounds;
 if(map.kind==='outdoor'){
  if(spot==='inside'&&!place.geometry.water)return{x:x+w/2,y:y+h/2};
  if(spot==='inside')return null;
  const candidates=place.geometry.open?[[x+w/2,y+h/2],[x+w/2,y+h+30]]:[[x+w/2,y+h+30],[x-15,y+h+25],[x+w+15,y+h+25]];
  const p=candidates.find(([x,y])=>map.safeFloor(x,y,7));return p?{x:p[0],y:p[1]}:null;
 }
 const room=place.geometry?.room,hall=place.geometry?.hall;
 if(hall)return {x:x+w/2,y:y+h/2};
 if(spot==='inside')return{x:x+w/2,y:y+h/2};
 const door=place.geometry?.door;
 if(!door){
  if(room?.circular&&map.geometry.special?.type==='tower'){const s=map.geometry.special;return{x:s.stemEnd-12,y:s.cy};}
  return null;
 }
 const ln=door.ln,at=door.at;
 const point=ln.axis==='H'?{x:at,y:ln.at}:{x:ln.at,y:at};
 if(spot==='threshold')return point;
 if(spot==='corridor'){
  const hall=ln.A?.kind==='hall'?ln.A:ln.B?.kind==='hall'?ln.B:null;if(!hall)return null;
  if(ln.axis==='H')point.y+=(hall.y>=ln.at?1:-1)*Math.min(30,hall.h/2);
  else point.x+=(hall.x>=ln.at?1:-1)*Math.min(30,hall.w/2);
  return map.safeFloor(point.x,point.y,5)?point:null;
 }
 if(spot==='outdoor'&&map.geometry.yard){const yard=map.geometry.yard;return{x:yard.x+yard.w/2,y:yard.y+yard.h/2};}
 return null;
}

let sceneData=null;
function inspect(place){put('#place-title',place?.name||sceneData.pcPlace||sceneData.meta.areaName);put('#activity',place?.overhear||'');put('#observation',[place?.description||place?.desc,...(place?.props||[]).map(p=>p.name+(p.state?' · '+p.state:''))].filter(Boolean).join('\n'));const actors=$('#actors');actors.replaceChildren();for(const a of sceneData.actors.filter(a=>!place||a.placeId===place.id||key(a.placeName)===key(place.name))){const row=actorTag(a,true);row.onclick=()=>{put('#place-title',a.name);put('#activity',place?.overhear||'');put('#observation',[a.activity,a.observation].filter(Boolean).join('\n'))};actors.append(row);}const events=sceneData.events.filter(e=>!place||e.placeId===place.id||key(e.placeName)===key(place.name));$('#quests').replaceChildren();put('#hintcount',String(events.length));for(const e of events){const row=document.createElement('button');row.className='event-row';row.textContent=e.title;row.onclick=()=>{put('#place-title',e.title);put('#observation',e.detail||'')};$('#quests').append(row);}}
async function renderInput(input){const renderStart=performance.now();root.parentElement.querySelectorAll('[data-rp-detail]').forEach(e=>e.remove());sceneData=normalize(input);const d=sceneData;
 if(!window.WZW_ORIGINAL_MAPS)window.WZW_ORIGINAL_MAPS=structuredClone(DATA.maps);DATA.maps=structuredClone(window.WZW_ORIGINAL_MAPS);
 const scene=resolve(d);let mapId=scene.source?(DATA.maps[d.atlasAnchor]?d.atlasAnchor:Object.keys(DATA.maps).find(k=>DATA.maps[k]===scene.source)):'rp-scene';if(scene.source){DATA.maps[mapId].places=scene.places.filter(p=>scene.source.places.some(x=>x.id===p.id));}else DATA.maps[mapId]=buildMap(scene,d);
 await setTemplate(mapId);if(scene.source&&scene.detail){const b=document.createElement('button');b.dataset.rpDetail='true';b.textContent='Xem khu/phòng RP bổ sung';b.onclick=async()=>{DATA.maps['rp-detail']=buildMap({...scene,places:scene.places.filter(p=>!scene.source.places.some(x=>x.id===p.id)||p.templateState==='structural_change')},d);await setTemplate('rp-detail');await mount();};$('#mapmount').parentElement.append(b);}
 async function mount(){for(const a of d.actors){const place=scene.exact(a.placeId||a.placeName);a.placeId=place?.id;if(a.isPC){a.placeName=d.pcPlace;a.placeId=scene.exact(d.pcPlace)?.id;a.spot=d.pcSpot;}a.inside=a.spot==='inside';a.scenePoint=undefined;a.unresolvedAnchor=false;const resolved=scene.exact(a.placeId||a.placeName);a.hearingText=resolved?.overhear||'';const map=DATA.maps[activeId];if(!scene.source&&resolved){a.scenePoint=generatedActorPoint(map,resolved,a.spot);if(!a.scenePoint)a.unresolvedAnchor=true;}if(a.inside)a.footstep='hidden';}for(const e of d.events)e.placeId=scene.exact(e.placeId||e.placeName)?.id;await presentation.mountActors(d.actors.filter(a=>a.placeId&&!a.unresolvedAnchor));presentation.mountEvents(d.events.filter(e=>e.placeId));svg.addEventListener('wzw-place-selected',e=>inspect(scene.places.find(p=>p.id===e.detail.id)));inspect(scene.exact(d.pcPlace));}
 await mount();put('#place-area',scene.source?'BẢN ĐỒ CỐ ĐỊNH':'KHÔNG GIAN RP');for(const [selector,value]of [['#zone',d.meta.areaName],['.quote',d.meta.quote],['.date',d.meta.date],['.clock',d.meta.time]]){const el=$(selector);if(el)el.textContent=value||'';}
 root.dataset.status='ready';root.dataset.renderMs=String(performance.now()-renderStart);window.WZW_SCENE={...scene,rendered:{kind:DATA.maps[activeId].kind,geometry:DATA.maps[activeId].geometry,footprints:DATA.maps[activeId].footprints},diagnostics:d.diagnostics};return scene;}
async function boot(){let input=window.MAP_DATA;try{const t=document.getElementById('map-data');if(t)input=JSON.parse(t.textContent)}catch{input={};root.dataset.transport='incomplete';}
 try{if(window.WZW_TEMPLATE_PACK){const b=Uint8Array.from(atob(window.WZW_TEMPLATE_PACK),c=>c.charCodeAt(0));DATA=JSON.parse(await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}else throw Error('Template pack unavailable');bindUI();window.MAP_DATA=input;await renderInput(input);if(root.dataset.transport==='incomplete'){root.dataset.status='incomplete';put('#observation','Dữ liệu MAP_DATA chưa đầy đủ hoặc sai JSON. Chưa dựng được cảnh RP được xác nhận.');}}
 catch{root.replaceChildren();const p=document.createElement('p');p.textContent=sceneData?.meta?.areaName||'Bản đồ RP';root.append(p);for(const item of [...(sceneData?.places||[]),...(sceneData?.actors||[]),...(sceneData?.events||[])]){const el=document.createElement('p');el.textContent=[item.name||item.title,item.description||item.activity||item.detail].filter(Boolean).join(' — ');root.append(el);}root.dataset.status='text-fallback';}}
